files={'mesh_scene18/analyze_alignment.py': {'text': '"""Recover and cross-validate the historical mesh coordinate transform."""\nimport json\nfrom pathlib import Path\nimport numpy as np\nfrom pxr import Usd, UsdGeom\n\nROOT=Path(\'/root/gpufree-data/IsaacSim_Asset\')\nOLD=ROOT/\'excavator_module_set/Sim_Fangshan_02\'\nNEW=ROOT/\'excavator_module_set/Excavator_3DGS_Contract\'\nMAPPING=[(\'track\',\'track\',\'track\'),(\'cab\',\'operator_cab\',\'operator_cab\'),(\'boom\',\'boom\',\'boom\'),(\'arm\',\'small_arm\',\'small_arm\')]\n\ndef positions(path):\n    stage=Usd.Stage.Open(str(path))\n    prim=next(p for p in stage.Traverse() if p.GetAttribute(\'positions\').HasAuthoredValueOpinion())\n    return np.asarray(prim.GetAttribute(\'positions\').Get(),dtype=np.float64)\n\ndef fit_rigid(x,y):\n    xc=x.mean(axis=0);yc=y.mean(axis=0)\n    u,s,vt=np.linalg.svd((x-xc).T@(y-yc))\n    d=np.eye(3);d[-1,-1]=np.linalg.det(u@vt)\n    r=u@d@vt;t=yc-xc@r\n    m=np.eye(4);m[:3,:3]=r;m[3,:3]=t\n    return m\n\ndef apply(points,m):return points@m[:3,:3]+m[3,:3]\ndef error(a,b):\n    e=np.linalg.norm(a-b,axis=1)\n    return {\'count\':len(e),\'max\':float(e.max()),\'rms\':float(np.sqrt(np.mean(e*e))),\'median\':float(np.median(e))}\n\nraw=positions(NEW/\'geometry/track.usdc\');aligned=positions(OLD/\'3dgs_usd/track.usd\')\nmatrix=fit_rigid(raw,aligned)\nreport={\'matrix_convention\':\'row vectors: corrected = raw @ R + translation\', \'raw_to_corrected\':matrix.tolist(), \'corrected_to_raw\':np.linalg.inv(matrix).tolist(),\'gaussian_checks\':{},\'mesh_checks\':{}}\nfor current,old,mesh in MAPPING:\n    a=positions(NEW/\'geometry\'/f\'{current}.usdc\');b=positions(OLD/\'3dgs_usd\'/f\'{old}.usd\')\n    if len(a)==len(b):report[\'gaussian_checks\'][current]=error(apply(a,matrix),b)\n    else:report[\'gaussian_checks\'][current]={\'raw_count\':len(a),\'aligned_count\':len(b),\'reason\':\'different count; no assumed index pairing\'}\nsource=Usd.Stage.Open(str(ROOT/\'excavator_module_set/sim_Fangshan_01/mechanic_parts_set/mesh_parts/拆分成五部分的mesh.usd\'))\nmp=source.GetPrimAtPath(\'/World/mesh_\')\npts=np.asarray(mp.GetAttribute(\'points\').Get(),dtype=np.float64)\nreport[\'raw_mesh_attributes\']=[{\'name\':a.GetName(),\'type\':str(a.GetTypeName())} for a in mp.GetAttributes() if a.HasAuthoredValueOpinion()]\ndest=Usd.Stage.Open(str(OLD/\'waji_mesh_corrected.usdc\'))\nfor prim in dest.Traverse():\n    if not prim.IsA(UsdGeom.Mesh):continue\n    name=prim.GetName().removesuffix(\'_mesh\')\n    dp=np.asarray(prim.GetAttribute(\'points\').Get(),dtype=np.float64)\n    attr=mp.GetAttribute(\'primvars:Group_\'+name)\n    row={\'corrected_vertices\':len(dp)}\n    if attr and attr.HasAuthoredValueOpinion():\n        weights=np.asarray(attr.Get());mask=weights>0.5;selected=pts[mask]\n        row[\'raw_vertices\']=len(selected)\n        if len(selected)==len(dp):row[\'index_correspondence_error\']=error(apply(selected,matrix),dp)\n    report[\'mesh_checks\'][name]=row\nreport[\'readme\']=(OLD/\'README.md\').read_text()[:10000]\ntry:\n    from scipy.spatial import cKDTree\n    corrected=np.concatenate([np.asarray(p.GetAttribute(\'points\').Get(),dtype=np.float64) for p in dest.Traverse() if p.IsA(UsdGeom.Mesh)])\n    predicted=apply(pts,matrix)\n    distance,_=cKDTree(corrected).query(predicted,workers=2)\n    reverse,_=cKDTree(predicted).query(corrected,workers=2)\n    report[\'mesh_global_correspondence\']={\'source_vertices\':len(pts),\'corrected_vertices\':len(corrected),\'forward_max\':float(distance.max()),\'reverse_max\':float(reverse.max()),\'forward_rms\':float(np.sqrt(np.mean(distance**2))),\'scipy_available\':True}\nexcept ImportError:\n    corrected=np.concatenate([np.asarray(p.GetAttribute(\'points\').Get(),dtype=np.float64) for p in dest.Traverse() if p.IsA(UsdGeom.Mesh)])\n    predicted=apply(pts,matrix)\n    def rowkeys(a):\n        a=np.ascontiguousarray(np.rint(a*1000).astype(np.int64))\n        return a.view(np.dtype((np.void,a.dtype.itemsize*3))).ravel()\n    distances=[]\n    for point in predicted[np.linspace(0,len(predicted)-1,128,dtype=int)]:\n        distances.append(float(np.sqrt(np.min(np.sum((corrected-point)**2,axis=1)))))\n    report[\'mesh_global_correspondence\']={\'scipy_available\':False,\'source_vertices\':len(pts),\'corrected_vertices\':len(corrected),\'rounded_1mm_vertex_match_fraction\':float(np.mean(np.isin(rowkeys(predicted),rowkeys(corrected)))),\'sampled_128_nearest_vertex_max\':max(distances),\'source_bounds\':predicted.min(axis=0).tolist()+predicted.max(axis=0).tolist(),\'corrected_bounds\':corrected.min(axis=0).tolist()+corrected.max(axis=0).tolist()}\nprint(json.dumps(report,ensure_ascii=False))\n', 'sha256': 'b9d9f252257f87779d248327d80ecd50776be82b15efe25530f529218f748425'}, 'mesh_scene18/build_assets.py': {'text': '"""Create the mesh-only contract asset and scene18; all existing assets stay untouched."""\nimport contextlib,hashlib,io,json,runpy,shutil,time\nfrom pathlib import Path\nimport numpy as np\nfrom pxr import Gf,Sdf,Usd,UsdGeom,UsdShade,Vt\n\nPROJECT=Path(\'/root/gpufree-data/semantic/scripts/260920SensorVisualizer\')\nWORK=PROJECT/\'mesh_scene18\'\nROOT=Path(\'/root/gpufree-data/IsaacSim_Asset\')\nSCENE=ROOT/\'combine_stage/combine_scene_17_terrain_fisheye.usda\'\nTARGET=ROOT/\'combine_stage/combine_scene_18_terrain_fisheye_mesh.usda\'\nOLD=ROOT/\'excavator_module_set/Excavator_3DGS_Contract/Excavator_3DGS_Contract.usda\'\nSOURCE=ROOT/\'excavator_module_set/Sim_Fangshan_02/waji_mesh_corrected.usdc\'\nBUNDLE=ROOT/\'excavator_module_set/Excavator_Mesh_Contract\'\nASSET=BUNDLE/\'Excavator_Mesh_Contract.usda\'\nPARTS={\'track_link\':\'track\',\'swing_link\':\'operator_cab\',\'boom_link\':\'boom\',\'arm_link\':\'small_arm\',\'bucket_link\':\'bucket_only_full_teeth\'}\ndef sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()\ndef dump(p,v):p.write_text(json.dumps(v,indent=2,ensure_ascii=False)+\'\\n\')\n\nfor p in (BUNDLE,TARGET):\n    assert p.resolve().is_relative_to(ROOT.resolve())\n    if p.exists():raise FileExistsError(\'Refusing to overwrite existing output: \'+str(p))\nbaseline=Usd.Stage.Open(str(SCENE))\nsource_files={l.realPath.split(\'[\',1)[0] for l in baseline.GetUsedLayers() if l.realPath}\nsource_hashes={p:sha(p) for p in sorted(source_files)}\nsource_hashes[str(SOURCE)]=sha(SOURCE)\nwith contextlib.redirect_stdout(io.StringIO()):\n    evidence=runpy.run_path(str(WORK/\'analyze_alignment.py\'))[\'report\']\nassert max(r[\'max\'] for r in evidence[\'gaussian_checks\'].values())<1e-6\nassert evidence[\'mesh_global_correspondence\'][\'rounded_1mm_vertex_match_fraction\']>.999\nassert evidence[\'mesh_global_correspondence\'][\'sampled_128_nearest_vertex_max\']<1e-6\ncorr=Gf.Matrix4d(*np.asarray(evidence[\'corrected_to_raw\']).ravel().tolist())\nstamp=time.strftime(\'%Y%m%dT%H%M%SZ\',time.gmtime())\nbackup=WORK/\'backups\'/stamp;backup.mkdir(parents=True,exist_ok=False)\nshutil.copy2(SCENE,backup/SCENE.name);shutil.copy2(OLD,backup/OLD.name)\ndump(backup/\'source_hashes.json\',source_hashes)\n(BUNDLE/\'geometry\').mkdir(parents=True,exist_ok=False)\ndump(WORK/\'alignment.json\',evidence)\nsource=Usd.Stage.Open(str(SOURCE))\nsource_layer=source.Flatten()\nmanifest={\'version\':\'mesh_contract_scene18_v1\',\'created_utc\':stamp,\'source_scene\':str(SCENE),\'source_scene_sha256\':sha(SCENE),\'source_mesh\':str(SOURCE),\'source_mesh_sha256\':sha(SOURCE),\'source_contract\':str(OLD),\'source_contract_sha256\':sha(OLD),\'coordinate_evidence\':evidence,\'parts\':{},\'bucket_policy\':\'Complete original bucket_only_full_teeth_mesh; no clipping or tooth removal\',\'geometry_policy\':\'Original mesh points/normals/topology retained; corrected-to-raw transform under existing Visuals; existing 2.4 scale remains only once\',\'material_policy\':\'Original linear RGBA vertex colors preserved as Col and mapped to displayColor; opaque UsdPreviewSurface roughness 0.8\',\'backup_directory\':str(backup)}\n\nSdf.Layer.FindOrOpen(str(OLD)).Export(str(ASSET))\nasset=Usd.Stage.Open(str(ASSET),load=Usd.Stage.LoadNone)\nfor frame,part in PARTS.items():\n    pp=f\'/root/{part}_mesh/{part}_mesh\'\n    source_prim=source.GetPrimAtPath(pp)\n    assert source_prim.IsA(UsdGeom.Mesh)\n    geo_file=BUNDLE/\'geometry\'/f\'{frame}.usdc\'\n    geo=Usd.Stage.CreateNew(str(geo_file))\n    root=UsdGeom.Xform.Define(geo,\'/Geometry\').GetPrim();geo.SetDefaultPrim(root)\n    UsdGeom.SetStageMetersPerUnit(geo,1);UsdGeom.SetStageUpAxis(geo,UsdGeom.Tokens.z)\n    assert Sdf.CopySpec(source_layer,pp,geo.GetRootLayer(),\'/Geometry/Mesh\')\n    mesh=geo.GetPrimAtPath(\'/Geometry/Mesh\')\n    colors=np.asarray(mesh.GetAttribute(\'primvars:Col\').Get())\n    points=np.asarray(mesh.GetAttribute(\'points\').Get())\n    assert len(colors)==len(points) and colors.shape[1]==4 and np.isfinite(colors).all()\n    assert np.max(np.abs(colors[:,3]-1))<1e-6\n    pv=UsdGeom.PrimvarsAPI(mesh).CreatePrimvar(\'displayColor\',Sdf.ValueTypeNames.Color3fArray,UsdGeom.Tokens.vertex)\n    pv.Set(Vt.Vec3fArray.FromNumpy(np.ascontiguousarray(colors[:,:3],dtype=np.float32)))\n    material=UsdShade.Material.Define(geo,\'/Geometry/Looks/VertexColor\')\n    shader=UsdShade.Shader.Define(geo,\'/Geometry/Looks/VertexColor/Surface\');shader.CreateIdAttr(\'UsdPreviewSurface\')\n    shader.CreateInput(\'roughness\',Sdf.ValueTypeNames.Float).Set(.8)\n    shader.CreateInput(\'metallic\',Sdf.ValueTypeNames.Float).Set(0)\n    reader=UsdShade.Shader.Define(geo,\'/Geometry/Looks/VertexColor/Color\');reader.CreateIdAttr(\'UsdPrimvarReader_float3\')\n    reader.CreateInput(\'varname\',Sdf.ValueTypeNames.Token).Set(\'displayColor\')\n    shader.CreateInput(\'diffuseColor\',Sdf.ValueTypeNames.Color3f).ConnectToSource(reader.CreateOutput(\'result\',Sdf.ValueTypeNames.Float3))\n    material.CreateSurfaceOutput().ConnectToSource(shader.CreateOutput(\'surface\',Sdf.ValueTypeNames.Token))\n    UsdShade.MaterialBindingAPI.Apply(mesh).Bind(material)\n    geo.GetRootLayer().Save()\n    visual=f\'/Excavator/{frame}/Visuals\'\n    assert asset.RemovePrim(visual+\'/Splat\')\n    alignment=UsdGeom.Xform.Define(asset,visual+\'/MeshAlignment\');alignment.AddTransformOp().Set(corr)\n    geometry=asset.DefinePrim(visual+\'/MeshAlignment/Geometry\')\n    geometry.GetPayloads().AddPayload(\'./geometry/\'+geo_file.name)\n    manifest[\'parts\'][frame]={\'source_prim\':pp,\'geometry_file\':str(geo_file),\'target_geometry_path\':visual+\'/MeshAlignment/Geometry/Mesh\',\'vertices\':len(points),\'faces\':len(mesh.GetAttribute(\'faceVertexCounts\').Get()),\'corrected_to_raw_row_matrix\':evidence[\'corrected_to_raw\'],\'link_from_raw_row_matrix\':[list(r) for r in UsdGeom.Xformable(asset.GetPrimAtPath(visual)).GetLocalTransformation()],\'topology_sha256\':hashlib.sha256(np.asarray(mesh.GetAttribute(\'faceVertexIndices\').Get()).tobytes()).hexdigest(),\'geometry_sha256\':sha(geo_file)}\nasset.GetRootLayer().Save()\nshutil.copy2(SCENE,TARGET)\nnew_layer=Sdf.Layer.FindOrOpen(str(TARGET))\nroot_spec=Sdf.CreatePrimInLayer(new_layer,\'/World/Excavator\')\nroot_spec.payloadList.explicitItems=[Sdf.Payload(\'../excavator_module_set/Excavator_Mesh_Contract/Excavator_Mesh_Contract.usda\')]\nmetadata=dict(new_layer.customLayerData)\nmetadata[\'meshReplacement\']={\'sourceScene\':str(SCENE),\'sourceSceneSha256\':sha(SCENE),\'meshAsset\':str(ASSET),\'bucketPolicy\':\'Preserve full teeth\',\'manifest\':str(BUNDLE/\'manifest.json\')}\nif \'omni_layer\' in metadata:\n    metadata[\'omni_layer\']=dict(metadata[\'omni_layer\']);metadata[\'omni_layer\'][\'authoring_layer\']=\'./\'+TARGET.name\nnew_layer.customLayerData=metadata;new_layer.Save()\nassert all(sha(p)==h for p,h in source_hashes.items()),\'Existing source changed during build\'\nmanifest.update(asset=str(ASSET),asset_sha256=sha(ASSET),scene=str(TARGET),scene_sha256=sha(TARGET),total_vertices=sum(x[\'vertices\'] for x in manifest[\'parts\'].values()),total_faces=sum(x[\'faces\'] for x in manifest[\'parts\'].values()),source_files_unchanged=True)\ndump(BUNDLE/\'manifest.json\',manifest);dump(WORK/\'build_manifest.json\',manifest)\nprint(json.dumps({\'asset\':str(ASSET),\'scene\':str(TARGET),\'total_vertices\':manifest[\'total_vertices\'],\'total_faces\':manifest[\'total_faces\'],\'sources_unchanged\':True,\'alignment_max_source_units\':max(r[\'max\'] for r in evidence[\'gaussian_checks\'].values())}))\n', 'sha256': '46c961ad85a19135409d6e63212187529237e416262284214906e17a2a892eb1'}, 'mesh_scene18/capture_supervisor.py': {'text': '"""Use the preserved v06 capture implementation; own only this test\'s processes."""\nimport hashlib,json,os,signal,subprocess,sys,time\nfrom pathlib import Path\nBASE=Path(\'/root/gpufree-data/semantic/scripts/260920SensorVisualizer\')\nWORK=BASE/\'mesh_scene18\';FROZEN=BASE/\'single06_lab/frozen_runtime\'\ncase=Path(sys.argv[1]).resolve()\nassert case.is_relative_to(Path(\'/root/gpufree-data/semantic/output/mesh_scene18\').resolve())\nsys.path.insert(0,str(FROZEN))\nfrom run_capture import launch_spec\nfor p in Path(\'/proc\').glob(\'[0-9]*/cmdline\'):\n    try:\n        if p.read_bytes().split(b\'\\0\')[0].endswith(b\'/kit/kit\'):raise RuntimeError(\'Existing Kit process; no process stopped\')\n    except OSError:pass\nscene=Path(json.loads((case/\'job.json\').read_text())[\'scene\']);before=hashlib.sha256(scene.read_bytes()).hexdigest()\nargs,env,cwd=launch_spec(case/\'job.json\',entry=FROZEN/\'kit_replay_entry.py\')\nenv[\'ROS_DOMAIN_ID\']=\'193\';env[\'ROS_LOCALHOST_ONLY\']=\'1\'\nstarted=time.monotonic();result={\'state\':\'running\',\'case\':str(case)}\n(case/\'result.json\').write_text(json.dumps(result))\nwith (case/\'engine.log\').open(\'xb\') as log:\n    child=subprocess.Popen(args,env=env,cwd=cwd,stdin=subprocess.DEVNULL,stdout=log,stderr=log,start_new_session=True)\n    result[\'kit_pid\']=child.pid;(case/\'result.json\').write_text(json.dumps(result))\n    try:child.wait(timeout=480)\n    except subprocess.TimeoutExpired:\n        (case/\'control.json\').write_text(\'{"action":"stop"}\')\n        try:child.wait(timeout=30)\n        except subprocess.TimeoutExpired:\n            os.killpg(child.pid,signal.SIGTERM);child.wait(timeout=20)\n    result.update(exit_code=child.returncode,process_wall_s=time.monotonic()-started)\nstatus=case/\'capture_status.json\'\nif status.exists():result[\'capture\']=json.loads(status.read_text())\ndef ros(argv):return subprocess.run([\'/bin/bash\',\'--noprofile\',\'--norc\',\'-c\',\'source /opt/ros/jazzy/setup.bash && exec /usr/bin/python3 "$@"\',\'scene18-validation\',*map(str,argv)],capture_output=True,text=True,timeout=180)\nif result[\'exit_code\']==0 and result.get(\'capture\',{}).get(\'state\')==\'finished\':\n    session=Path(result[\'capture\'][\'session\'])\n    p=ros([BASE/\'single06_lab/tools/validate_capture_data.py\',session]);(case/\'validation.log\').write_text(p.stdout+p.stderr)\n    result[\'validation_exit_code\']=p.returncode\n    for line in p.stdout.splitlines():\n        if line.startswith(\'VALIDATION_JSON=\'):result[\'validation\']=json.loads(line.split(\'=\',1)[1])\n    (case/\'capture\').mkdir(exist_ok=True);(case/\'capture/result.json\').write_text(json.dumps(result))\n    p=ros([BASE/\'capture_comparison_004/tools/decode_case.py\',case]);(case/\'decode.log\').write_text(p.stdout+p.stderr);result[\'decode_exit_code\']=p.returncode\nresult[\'scene_unchanged\']=hashlib.sha256(scene.read_bytes()).hexdigest()==before\nresult[\'state\']=\'completed\' if result.get(\'validation\',{}).get(\'passed\') and result.get(\'decode_exit_code\')==0 and result[\'scene_unchanged\'] else \'failed\'\n(case/\'result.json\').write_text(json.dumps(result,indent=2));print(json.dumps(result))\n', 'sha256': '8929496c6173b40bb756b201dc6af95570db4b5a03d7f35decce71dbc0c34b92'}, 'mesh_scene18/final_verify.py': {'text': '"""Final source and generated-asset checks after real engine validation."""\nimport hashlib,json\nfrom pathlib import Path\nwork=Path(\'/root/gpufree-data/semantic/scripts/260920SensorVisualizer/mesh_scene18\')\nm=json.loads((work/\'build_manifest.json\').read_text())\nhashes=json.loads((Path(m[\'backup_directory\'])/\'source_hashes.json\').read_text())\ndef sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()\nchanged=[p for p,h in hashes.items() if sha(p)!=h]\ngenerated={m[\'asset\']:m[\'asset_sha256\'],m[\'scene\']:m[\'scene_sha256\'],**{r[\'geometry_file\']:r[\'geometry_sha256\'] for r in m[\'parts\'].values()}}\nchanged_new=[p for p,h in generated.items() if sha(p)!=h]\nlatest=json.loads((work/\'latest_capture.json\').read_text());case=Path(latest[\'case\']);result=json.loads((case/\'result.json\').read_text())\nkit=[]\nfor p in Path(\'/proc\').glob(\'[0-9]*/cmdline\'):\n    try:\n        if p.read_bytes().split(b\'\\0\')[0].endswith(b\'/kit/kit\'):kit.append(int(p.parent.name))\n    except OSError:pass\nlines=(case/\'engine.log\').read_text(errors=\'replace\').splitlines()\nreport={\'passed\':not changed and not changed_new and result[\'state\']==\'completed\',\'checked_source_files\':len(hashes),\'changed_source_files\':changed,\'changed_generated_files\':changed_new,\'capture_state\':result[\'state\'],\'kit_processes_now\':kit,\'engine_error_lines\':sum(\'[Error]\' in s for s in lines),\'engine_warning_lines\':sum(\'[Warning]\' in s for s in lines),\'remote_scene\':m[\'scene\'],\'source_scene_preserved\':m[\'source_scene\'],\'local_mirrors\':\'Transferred separately with audited SFTP and per-file SHA256; not a claim of standalone combine dependencies.\'}\n(work/\'final_verification.json\').write_text(json.dumps(report,indent=2));print(json.dumps(report));assert report[\'passed\']\n', 'sha256': '508fda6be7899f948ef1d74d013cb24e939441625ab709402eaad3225e0be74d'}, 'mesh_scene18/prepare_capture.py': {'text': '"""Generate a three-pose trajectory from scene18\'s own sensor mounts."""\nimport hashlib,json,os,sys\nfrom pathlib import Path\nfrom pxr import Gf,Usd,UsdGeom\nBASE=Path(\'/root/gpufree-data/semantic/scripts/260920SensorVisualizer\')\nFROZEN=BASE/\'single06_lab/frozen_runtime\'\nsys.path.insert(0,str(FROZEN))\nfrom sensor_visualizer_v06.robot.discovery import discover_sensors\nfrom sensor_visualizer_v06.robot.sensor_pose import SensorPoses\nfrom sensor_visualizer_v06.contracts import load_job\n\ncase=Path(CASE_OUTPUT)\ncase.mkdir(parents=True,exist_ok=False)\nscene=Path(\'/root/gpufree-data/IsaacSim_Asset/combine_stage/combine_scene_18_terrain_fisheye_mesh.usda\')\nstage=Usd.Stage.Open(str(scene))\nsensors=discover_sensors(stage,robot_path=\'/World/Excavator\')\nfor cid,name in [(\'front\',\'Front\'),(\'back\',\'Rear\'),(\'left\',\'Left\'),(\'right\',\'Right\')]:\n    sensors.append({\'id\':\'camera_\'+cid,\'prim_path\':\'/World/Excavator/swing_link/Fisheye\'+name})\nposes=SensorPoses(stage,sensors,str(case),lambda:0.)\nmounts=poses.snapshot();poses.close()\nbase=UsdGeom.Xformable(stage.GetPrimAtPath(\'/World/Excavator\')).ComputeLocalToWorldTransform(Usd.TimeCode.Default())\ntraj=case/\'input_trajectory\';traj.mkdir()\nrows=[]\nfor group,(sign,xyz,rpy) in enumerate([(0,(0,0,0),(0,0,0)),(1,(.2,-.1,.1),(3,-4,10)),(-1,(-.2,.1,.05),(-3,4,-10))]):\n    m=Gf.Matrix4d(base)\n    rotate=Gf.Rotation(Gf.Vec3d(1,0,0),rpy[0])*Gf.Rotation(Gf.Vec3d(0,1,0),rpy[1])*Gf.Rotation(Gf.Vec3d(0,0,1),rpy[2])\n    m=Gf.Matrix4d().SetRotate(rotate)*m\n    m.SetTranslateOnly(base.ExtractTranslation()+Gf.Vec3d(*xyz));q=m.ExtractRotationQuat().GetNormalized()\n    rows.append({\'schema_version\':1,\'session_id\':\'scene18_validation\',\'snapshot_id\':f\'scene18_pose_{group}\',\'seq\':group,\'state_revision\':group,\'mount_revision\':0,\'t_sim_s\':group/10,\'position_world_m\':list(m.ExtractTranslation()),\'quaternion_xyzw\':[*q.GetImaginary(),q.GetReal()],\'joints_deg\':{n:sign*15. for n in (\'boom\',\'arm\',\'bucket\')},\'transition_kind\':\'step\'})\nmetadata={\'schema_version\':1,\'recording_complete\':True,\'joint_names\':[\'boom\',\'arm\',\'bucket\'],\'mount_revisions\':{\'0\':mounts},\'initial_mounts\':mounts,\'asset_manifest\':{\'root_sha256\':hashlib.sha256(scene.read_bytes()).hexdigest()},\'last_time_s\':.2,\'rows\':3}\n(traj/\'metadata.json\').write_text(json.dumps(metadata,indent=2))\n(traj/\'states.jsonl\').write_text(\'\'.join(json.dumps(r)+\'\\n\' for r in rows))\njob=load_job(overrides={\'scene\':str(scene),\'groups\':3,\'output_directory\':str(case/\'captures\'),\'capture\':{\'resource_policy\':\'keepalive\'},\'diagnostics\':{\'level\':\'diagnostic\'},\'replay\':{\'mode\':\'offline\',\'trajectory\':str(traj),\'control_path\':str(case/\'control.json\'),\'status_path\':str(case/\'capture_status.json\'),\'socket\':str(case/\'engine.sock\')}})\n(case/\'job.json\').write_text(json.dumps(job,indent=2))\n(case/\'config.json\').write_text(json.dumps({\'family\':\'v06\',\'requested_groups\':3,\'id\':\'scene18_mesh_motion_smoke\'}))\nprint(json.dumps({\'case\':str(case),\'job\':str(case/\'job.json\'),\'poses\':3,\'mounts\':len(mounts)}))\n', 'sha256': '8ff5113c24865fedc11bbae37f5d71195ce3d83e08e4276d2823a065b2bc674f'}, 'mesh_scene18/probe_sources.py': {'text': '"""Read source coordinate evidence and engine availability; never edits remote data."""\nimport json, os, subprocess\nfrom pathlib import Path\ninstall=Path(\'/root/isaacsim\')\nsdk=sorted((install/\'extscache\').glob(\'omni.usd.libs-*/pxr\'))[-1].parent\nenv=os.environ.copy()\nfor key in (\'PYTHONHOME\',\'PYTHONPATH\',\'LD_PRELOAD\',\'LD_LIBRARY_PATH\',\'VIRTUAL_ENV\',\'CONDA_PREFIX\'):env.pop(key,None)\nenv[\'LD_LIBRARY_PATH\']=\':\'.join(map(str,(install/\'kit/python/lib\',install/\'kit\',sdk/\'bin\',sdk/\'lib\')))\ncode=r\'\'\'\nimport sys,json,hashlib\nfrom pathlib import Path\nsys.path.insert(0,SDK)\nfrom pxr import Usd,UsdGeom,Sdf\nroot=Path(\'/root/gpufree-data/IsaacSim_Asset\')\nfolder=root/\'excavator_module_set/Sim_Fangshan_02\'\nresult={\'small_files\':[],\'files\':{},\'stages\':{},\'existing_targets\':[]}\nfor p in folder.rglob(\'*\'):\n if p.is_file() and p.suffix in (\'.json\',\'.md\',\'.py\') and p.stat().st_size<100000:\n  result[\'small_files\'].append(str(p.relative_to(folder)))\nfor name in [\'combine_stage/combine_scene_17_terrain_fisheye.usda\',\'combine_stage/combine_scene_18_terrain_fisheye_mesh.usda\',\'excavator_module_set/Excavator_Mesh_Contract/Excavator_Mesh_Contract.usda\']:\n p=root/name\n if p.exists():result[\'existing_targets\'].append({\'path\':str(p),\'sha256\':hashlib.sha256(p.read_bytes()).hexdigest()})\npaths={\'raw_track\':root/\'excavator_module_set/Excavator_3DGS_Contract/geometry/track.usdc\',\'aligned_track\':folder/\'3dgs_usd/track.usd\',\'corrected_mesh\':folder/\'waji_mesh_corrected.usdc\'}\nfor key,path in paths.items():\n stage=Usd.Stage.Open(str(path));rows=[]\n for prim in stage.Traverse():\n  row={\'path\':str(prim.GetPath()),\'type\':prim.GetTypeName(),\'custom_data\':str(prim.GetCustomData())[:8000]}\n  if prim.IsA(UsdGeom.Xformable):row[\'local\']=str(UsdGeom.Xformable(prim).GetLocalTransformation())\n  row[\'attributes\']=[]\n  for a in prim.GetAttributes():\n   if a.HasAuthoredValueOpinion():\n    v=a.Get();n=len(v) if hasattr(v,\'__len__\') else None\n    small=str(v) if n is None or n<17 else str(v[:2])\n    row[\'attributes\'].append({\'name\':a.GetName(),\'type\':str(a.GetTypeName()),\'length\':n,\'value\':small[:1200]})\n  row[\'relationships\']={r.GetName():[str(t) for t in r.GetTargets()] for r in prim.GetRelationships() if r.HasAuthoredTargets()}\n  rows.append(row)\n result[\'stages\'][key]={\'metadata\':str(stage.GetRootLayer().customLayerData)[:10000],\'rows\':rows}\nprint(json.dumps(result))\n\'\'\'.replace(\'SDK\',repr(str(sdk)))\np=subprocess.run([str(install/\'kit/python/bin/python3\'),\'-I\',\'-S\',\'-B\',\'-\'],input=code,env=env,capture_output=True,text=True,timeout=65)\nresult={\'returncode\':p.returncode,\'stderr\':p.stderr[-4000:],\'data\':json.loads(p.stdout) if p.returncode==0 else p.stdout[-4000:]}\nresult[\'kit_processes\']=[]\nfor proc in Path(\'/proc\').iterdir():\n if not proc.name.isdigit():continue\n try:\n  comm=(proc/\'comm\').read_text().strip()\n  if comm in (\'kit\',\'isaac-sim\'):\n   result[\'kit_processes\'].append({\'pid\':proc.name,\'cmd\':(proc/\'cmdline\').read_bytes().replace(b\'\\x00\',b\' \').decode()[:1800]})\n except (OSError,PermissionError):pass\ngpu=subprocess.run([\'nvidia-smi\',\'--query-gpu=name,memory.used,memory.total,utilization.gpu\',\'--format=csv,noheader\'],capture_output=True,text=True,timeout=15)\nresult[\'gpu\']=gpu.stdout\nprint(json.dumps(result))\n', 'sha256': '912cbd0ac195f1f00abbab41c248eca1e91ed0a7f29d6e8a8e9eaeacce0247d4'}, 'mesh_scene18/pull_artifacts.py': {'text': '"""Read self-generated lab evidence over audited SFTP (CLI has no file-transfer verb).\n\nUses existing credential references and fingerprint/instance validation. No cloud\nfile writes. Hash consistency is transfer evidence, not software trust assurance.\n"""\nimport argparse,hashlib,json,os,sys,warnings\nfrom pathlib import Path,PurePosixPath\nROOT=Path(__file__).resolve().parent\nsys.path.insert(0,\'C:/Users/15452/.codex/skills/cloud-instance-ops/scripts\')\nfrom cloud_ops.audit import Audit\nfrom cloud_ops.security import Redactor,WindowsCredentials,private_directory\nfrom cloud_ops.ssh import check_fingerprint,check_identity,remote_python,IDENTITY_SCRIPT\nwith warnings.catch_warnings():\n    warnings.simplefilter(\'ignore\');import paramiko\n\np=argparse.ArgumentParser();p.add_argument(\'remote_directory\');p.add_argument(\'--destination\',required=True);p.add_argument(\'--exclude-name\',action=\'append\',default=[]);p.add_argument(\'--include-path\',action=\'append\',default=[]);a=p.parse_args()\nremote=PurePosixPath(a.remote_directory)\nif not any(remote.is_relative_to(PurePosixPath(r)) for r in (\'/root/gpufree-data/semantic/output/mesh_scene18\',\'/root/gpufree-data/semantic/scripts/260920SensorVisualizer/mesh_scene18\',\'/root/gpufree-data/IsaacSim_Asset/excavator_module_set/Excavator_Mesh_Contract\',\'/root/gpufree-data/IsaacSim_Asset/combine_stage\')):\n    raise ValueError(\'Only native baseline output is allowed\')\nprofile=ROOT.parent/\'migrations/20261010_dual_gpu/targets.json\'\ntarget=json.loads(profile.read_text())[\'targets\'][\'isaac-new\'];redactor=Redactor()\nkwargs=dict(hostname=target[\'host\'],port=target[\'port\'],username=target[\'username\'],\n            look_for_keys=False,allow_agent=False,timeout=15,banner_timeout=15,auth_timeout=15)\nif target[\'auth\']==\'windows-credential\':\n    value=WindowsCredentials().read(target[\'credential_ref\']);redactor.add_secret(value);kwargs[\'password\']=value\nelif target[\'auth\']==\'key\':kwargs[\'key_filename\']=target[\'identity_file\']\nelse:raise ValueError(\'Unsupported credential reference\')\naudit=Audit(private_directory(Path(os.environ[\'LOCALAPPDATA\'])/\'CloudInstanceOps\'),redactor,\'scene18-mesh-implementation-20261012\',\n            \'Transfer generated scene18 assets and validation evidence to the local project\',\n            \'project-evidence-sftp\',hashlib.sha256(profile.read_bytes()).hexdigest())\nclient=paramiko.SSHClient()\nclass Pin(paramiko.MissingHostKeyPolicy):\n    def missing_host_key(self,client,hostname,key):\n        check_fingerprint(key,target[\'host_fingerprint\']);audit.event(\'ssh.host_key.verified\',target_alias=\'isaac-new\')\nclient.set_missing_host_key_policy(Pin())\ndestination=Path(a.destination).resolve();destination.mkdir(parents=True,exist_ok=True)\ntry:\n    audit.event(\'ssh.connect.requested\',target_alias=\'isaac-new\',channel=\'SFTP through existing Paramiko; CLI transfer unsupported\')\n    client.connect(**kwargs)\n    identity=remote_python(client,IDENTITY_SCRIPT,audit,\'identity\',15)\n    if identity[\'exit_code\']:raise RuntimeError(\'Identity query failed\')\n    check_identity(json.loads(identity[\'stdout\']),target);audit.event(\'ssh.instance.verified\',target_alias=\'isaac-new\')\n    script="""import hashlib,json\nfrom pathlib import Path\nroot=Path(REMOTE)\nassert root.resolve()==root\nallowed={\'.json\',\'.jsonl\',\'.csv\',\'.log\',\'.sqlite\',\'.nsys-rep\',\'.jpg\',\'.png\',\'.md\',\'.html\',\'.usda\',\'.usdc\'}\nexcluded=EXCLUDED\nincluded=INCLUDED\nrows=[]\nfor p in sorted(root.rglob(\'*\')):\n if not p.is_file() or p.suffix not in allowed or any(x in p.relative_to(root).parts for x in (\'input_trajectory\',\'bag_unified\')):continue\n if included and p.relative_to(root).as_posix() not in included:continue\n if p.name in excluded:continue\n if any(x.startswith(\'round_\') for x in root.parts) and p.name==\'progress.json\':continue\n assert p.resolve().is_relative_to(root)\n if p.stat().st_size>512*1024**2:raise RuntimeError(\'Large artifact requires explicit selection\')\n h=hashlib.sha256()\n with p.open(\'rb\') as f:\n  for block in iter(lambda:f.read(1024**2),b\'\'):h.update(block)\n rows.append({\'path\':p.relative_to(root).as_posix(),\'bytes\':p.stat().st_size,\'sha256\':h.hexdigest()})\nassert sum(r[\'bytes\'] for r in rows)<2*1024**3\nprint(json.dumps(rows))\n""".replace(\'REMOTE\',repr(str(remote))).replace(\'EXCLUDED\',repr(a.exclude_name)).replace(\'INCLUDED\',repr(a.include_path))\n    audit.event(\'artifact.transfer.scope\',excluded_names=a.exclude_name,included_paths=a.include_path)\n    audit.snapshot(\'manifest_query\',script)\n    response=remote_python(client,script,audit,\'artifact-manifest\',60)\n    if response[\'exit_code\'] or any(response[\'output_omitted\']):raise RuntimeError(\'Manifest query failed\')\n    manifest=json.loads(response[\'stdout\']);sftp=client.open_sftp()\n    for row in manifest:\n        dest=destination/row[\'path\']\n        if not dest.resolve().is_relative_to(destination):raise ValueError(\'Unexpected artifact path\')\n        dest.parent.mkdir(parents=True,exist_ok=True)\n        if dest.is_file() and hashlib.sha256(dest.read_bytes()).hexdigest()==row[\'sha256\']:continue\n        if dest.exists():raise FileExistsError(\'Existing differing evidence: \'+str(dest))\n        partial=dest.with_suffix(dest.suffix+\'.part\')\n        if partial.exists():raise FileExistsError(str(partial))\n        sftp.get(str(remote/row[\'path\']),str(partial))\n        if partial.stat().st_size!=row[\'bytes\'] or hashlib.sha256(partial.read_bytes()).hexdigest()!=row[\'sha256\']:\n            raise RuntimeError(\'Transfer mismatch; partial retained\')\n        partial.rename(dest);audit.event(\'artifact.transfer.verified\',source=str(remote/row[\'path\']),\n            local_path=str(dest),bytes=row[\'bytes\'],sha256=row[\'sha256\'])\n    sftp.close();(destination/\'transfer_manifest.json\').write_text(json.dumps(manifest,indent=2))\n    audit.finish(\'succeeded\');print(json.dumps({\'files\':len(manifest),\'bytes\':sum(r[\'bytes\'] for r in manifest),\n        \'destination\':str(destination),\'audit_log\':str(audit.path)},indent=2))\nexcept BaseException as exc:\n    audit.finish(\'failed\',error_type=type(exc).__name__,error=redactor.text(str(exc)));raise\nfinally:client.close()\n', 'sha256': 'ba3f3b1c81f9ab1a8a8fe4dd711705e218b2bd5789da54e4e8e3e07ac73e2cbf'}, 'mesh_scene18/runtime.py': {'text': '"""Launch existing USD Python without Kit or downloaded dependencies."""\nimport os\nimport subprocess\nfrom pathlib import Path\n\n\ndef run(source, timeout=120):\n    install = Path(\'/root/isaacsim\')\n    sdk = sorted((install/\'extscache\').glob(\'omni.usd.libs-*/pxr\'))[-1].parent\n    env = os.environ.copy()\n    for key in (\'PYTHONHOME\',\'PYTHONPATH\',\'LD_PRELOAD\',\'LD_LIBRARY_PATH\',\'VIRTUAL_ENV\',\'CONDA_PREFIX\'):\n        env.pop(key, None)\n    env[\'LD_LIBRARY_PATH\'] = \':\'.join(map(str, (install/\'kit/python/lib\', install/\'kit\', sdk/\'bin\', sdk/\'lib\')))\n    bootstrap = \'\'\'import sys\nfrom pathlib import Path\nsys.path.insert(0, {sdk!r})\nfor folder in [Path(\'/root/isaacsim/kit/python/lib/python3.12/site-packages\'), *sorted(Path(\'/root/isaacsim/extscache\').glob(\'omni.kit.pip_archive-*/pip_prebundle\'))]:\n    if folder.is_dir():sys.path.append(str(folder))\n\'\'\'.format(sdk=str(sdk))\n    completed = subprocess.run([str(install/\'kit/python/bin/python3\'), \'-I\',\'-S\',\'-B\',\'-\'],\n                               input=bootstrap+\'\\n\'+source, env=env, text=True,\n                               capture_output=True, timeout=timeout)\n    return completed\n', 'sha256': '463fa3bb8cd54d02bbef23988fa259aa00f2371fbbafba9804baf136fea53a6a'}, 'mesh_scene18/start_capture.py': {'text': '"""Prepare scene18-only validation job and launch its finite supervisor."""\nimport json,subprocess,sys,time\nfrom pathlib import Path\nwork=Path(\'/root/gpufree-data/semantic/scripts/260920SensorVisualizer/mesh_scene18\')\nsys.path.insert(0,str(work))\nfrom runtime import run\nassert json.loads((work/\'validation.json\').read_text())[\'passed\']\ncase=Path(\'/root/gpufree-data/semantic/output/mesh_scene18\')/time.strftime(\'smoke_%Y%m%d_%H%M%S\',time.gmtime())\nscript=(work/\'prepare_capture.py\').read_text().replace(\'CASE_OUTPUT\',repr(str(case)))\np=run(script);print(p.stdout);print(p.stderr)\nif p.returncode:raise SystemExit(p.returncode)\nwith (case/\'supervisor.log\').open(\'xb\') as log:\n    child=subprocess.Popen([\'/usr/bin/python3\',\'-u\',str(work/\'capture_supervisor.py\'),str(case)],stdin=subprocess.DEVNULL,stdout=log,stderr=log,start_new_session=True,cwd=work)\nstate={\'case\':str(case),\'supervisor_pid\':child.pid}\n(work/\'latest_capture.json\').write_text(json.dumps(state));print(json.dumps(state))\n', 'sha256': '7395e41b05f21e23dc2128cd4c37f7438a1372c3f76ae747dfb8c17f9550cf0d'}, 'mesh_scene18/status_capture.py': {'text': '"""Read only this task\'s finite capture results and bounded warning excerpts."""\nimport json,collections\nfrom pathlib import Path\nwork=Path(\'/root/gpufree-data/semantic/scripts/260920SensorVisualizer/mesh_scene18\')\nlatest=json.loads((work/\'latest_capture.json\').read_text());case=Path(latest[\'case\'])\nout={\'latest\':latest}\nfor name in (\'result.json\',\'capture_status.json\',\'decoded.json\'):\n    p=case/name\n    if p.is_file():out[name]=json.loads(p.read_text())\nfor name in (\'engine.log\',\'supervisor.log\',\'validation.log\',\'decode.log\'):\n    p=case/name\n    if p.is_file():\n        lines=p.read_text(errors=\'replace\').splitlines()\n        out[name]={\'tail\':lines[-16:],\'warnings\':len([l for l in lines if \'[Warning]\' in l]),\'errors\':len([l for l in lines if \'[Error]\' in l])}\n        if name==\'engine.log\':out[name][\'warning_error_examples\']=list(dict.fromkeys(l.split(\'] \',2)[-1] for l in lines if \'[Warning]\' in l or \'[Error]\' in l))[:35]\nprint(json.dumps(out))\n', 'sha256': '824d3f1baacd5aeafdc7446c7f229b429e87bc26214d1c8187fed7af6ab20404'}, 'mesh_scene18/validate_assets.py': {'text': '"""Validate geometry replacement, unchanged scene contract, and in-memory kinematics."""\nimport hashlib,json,sys\nfrom pathlib import Path\nimport numpy as np\nfrom pxr import Usd,UsdGeom,UsdShade,Gf,Sdf\n\nROOT=Path(\'/root/gpufree-data/IsaacSim_Asset\')\nPROJECT=Path(\'/root/gpufree-data/semantic/scripts/260920SensorVisualizer\')\nWORK=PROJECT/\'mesh_scene18\'\nmanifest=json.loads((WORK/\'build_manifest.json\').read_text())\nbefore=Usd.Stage.Open(manifest[\'source_scene\']);after=Usd.Stage.Open(manifest[\'scene\'])\nPARTS=list(manifest[\'parts\'])\ndef sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()\ndef excluded(path):return any(path.startswith(\'/World/Excavator/\'+f+\'/Visuals/\') for f in PARTS)\ndef canonical(v):\n    if isinstance(v,Sdf.AssetPath):return {\'asset\':v.resolvedPath or v.path}\n    if isinstance(v,dict):return {str(k):canonical(x) for k,x in v.items()}\n    if isinstance(v,(str,int,bool,float)) or v is None:return v\n    if isinstance(v,(list,tuple)):return [canonical(x) for x in v]\n    if type(v).__module__.startswith(\'pxr.Vt\'):\n        try:return {\'array_type\':type(v).__name__,\'count\':len(v),\'sha256\':hashlib.sha256(memoryview(v).tobytes()).hexdigest()}\n        except TypeError:return [canonical(x) for x in v]\n    return str(v)\ndef signature(prim):\n    attrs={}\n    for a in prim.GetAttributes():\n        if not a.HasAuthoredValueOpinion():continue\n        times=a.GetTimeSamples()\n        attrs[a.GetName()]={\'default\':canonical(a.Get()),\'samples\':{str(t):canonical(a.Get(t)) for t in times},\'metadata\':canonical({k:v for k,v in a.GetAllMetadata().items() if k not in (\'default\',\'timeSamples\')})}\n    return {\'type\':prim.GetTypeName(),\'active\':prim.IsActive(),\'instanceable\':prim.IsInstanceable(),\'schemas\':prim.GetAppliedSchemas(),\'custom_data\':canonical(prim.GetCustomData()),\'attributes\':attrs,\'relationships\':{r.GetName():[str(t) for t in r.GetTargets()] for r in prim.GetRelationships()}}\nleft={str(p.GetPath()):signature(p) for p in before.TraverseAll() if not excluded(str(p.GetPath()))}\nright={str(p.GetPath()):signature(p) for p in after.TraverseAll() if not excluded(str(p.GetPath()))}\ndifferences=[p for p in sorted(set(left)|set(right)) if left.get(p)!=right.get(p)]\nactive_gs=[str(p.GetPath()) for p in after.Traverse() if \'Gaussian\' in p.GetTypeName()]\nworld_errors={};a=UsdGeom.XformCache();b=UsdGeom.XformCache()\nfor p in before.Traverse():\n    path=str(p.GetPath())\n    if excluded(path) or not p.IsA(UsdGeom.Xformable):continue\n    q=after.GetPrimAtPath(path)\n    world_errors[path]=float(np.max(np.abs(np.asarray(a.GetLocalToWorldTransform(p))-np.asarray(b.GetLocalToWorldTransform(q)))))\nsource=Usd.Stage.Open(manifest[\'source_mesh\']);geometry=[]\nfor frame,row in manifest[\'parts\'].items():\n    src=source.GetPrimAtPath(row[\'source_prim\']);dst=after.GetPrimAtPath(row[\'target_geometry_path\'].replace(\'/Excavator/\',\'/World/Excavator/\',1))\n    checks={n:np.array_equal(np.asarray(src.GetAttribute(n).Get()),np.asarray(dst.GetAttribute(n).Get())) for n in (\'points\',\'faceVertexCounts\',\'faceVertexIndices\',\'normals\',\'primvars:Col\')}\n    material,_=UsdShade.MaterialBindingAPI(dst).ComputeBoundMaterial()\n    assert material and material.GetPrim().IsValid()\n    pts=np.asarray(dst.GetAttribute(\'points\').Get(),dtype=np.float64)\n    m=np.asarray(b.GetLocalToWorldTransform(dst));world=pts@m[:3,:3]+m[3,:3]\n    geometry.append({\'frame\':frame,\'copied_arrays_equal\':checks,\'bound_material\':str(material.GetPath()),\'world_mesh_vertex_bounds\':{\'min\':world.min(axis=0).tolist(),\'max\':world.max(axis=0).tolist()},\'world_mesh_vertex_dimensions_m\':(world.max(axis=0)-world.min(axis=0)).tolist()})\n\nsys.path.insert(0,str(PROJECT/\'tools\'))\nfrom contract_math import load_config,forward,rotation,transform\ncfg=load_config();motion=[]\nbase0=np.asarray(a.GetLocalToWorldTransform(before.GetPrimAtPath(\'/World/Excavator\'))).copy()\nfor stage in (before,after):stage.SetEditTarget(stage.GetSessionLayer())\nposes=[(\'bind\',{},(0,0,0),(0,0,0)),(\'all_positive\',{\'swing\':15,\'boom\':15,\'arm\':15,\'bucket\':15},(1,-.5,.2),(5,-7,20)),(\'all_negative\',{\'swing\':-15,\'boom\':-15,\'arm\':-15,\'bucket\':-15},(-.5,.3,-.1),(-5,7,-20))]\nfor joint in (\'boom\',\'arm\',\'bucket\'):\n    poses.extend([(joint+\'_positive\',{joint:15},(0,0,0),(0,0,0)),(joint+\'_negative\',{joint:-15},(0,0,0),(0,0,0))])\nfor name,angles,translation,rpy in poses:\n    base=base0@transform(translation,rotation(\'Z\',rpy[2])@rotation(\'Y\',rpy[1])@rotation(\'X\',rpy[0])).T\n    frames=forward(cfg,angles)\n    for stage in (before,after):\n        for path,m in [(\'/World/Excavator\',base),*[(f\'/World/Excavator/{f}\',frames[f].T) for f in PARTS]]:\n            xf=UsdGeom.Xformable(stage.GetPrimAtPath(path));xf.ClearXformOpOrder();xf.AddTransformOp(opSuffix=\'meshValidation\').Set(Gf.Matrix4d(*m.ravel().tolist()))\n    caches=[UsdGeom.XformCache(),UsdGeom.XformCache()];err=0\n    for path in world_errors:\n        if path.startswith(\'/World/Excavator\'):\n            err=max(err,float(np.max(np.abs(np.asarray(caches[0].GetLocalToWorldTransform(before.GetPrimAtPath(path)))-np.asarray(caches[1].GetLocalToWorldTransform(after.GetPrimAtPath(path)))))))\n    geometry_err=0\n    correction=np.asarray(manifest[\'coordinate_evidence\'][\'corrected_to_raw\'])\n    for frame,row in manifest[\'parts\'].items():\n        old_visual=before.GetPrimAtPath(f\'/World/Excavator/{frame}/Visuals\')\n        new_mesh=after.GetPrimAtPath(row[\'target_geometry_path\'].replace(\'/Excavator/\',\'/World/Excavator/\',1))\n        expected=correction@np.asarray(caches[0].GetLocalToWorldTransform(old_visual))\n        geometry_err=max(geometry_err,float(np.max(np.abs(expected-np.asarray(caches[1].GetLocalToWorldTransform(new_mesh))))))\n    motion.append({\'case\':name,\'angles_deg\':angles,\'max_preserved_world_matrix_error\':err,\'max_mesh_transform_chain_error\':geometry_err,\'scope\':\'in-memory prescribed kinematics; no PhysX dynamics claimed\'})\nhashes=json.loads((Path(manifest[\'backup_directory\'])/\'source_hashes.json\').read_text())\nunchanged=all(sha(p)==h for p,h in hashes.items())\nreport={\'passed\':not differences and not active_gs and max(world_errors.values())<1e-10 and unchanged and all(all(r[\'copied_arrays_equal\'].values()) for r in geometry) and all(r[\'max_mesh_transform_chain_error\']<1e-10 for r in motion),\'source_files_unchanged\':unchanged,\'compared_non_geometry_prims\':len(left),\'non_geometry_differences\':differences,\'active_gaussian_prims\':active_gs,\'max_static_world_matrix_error\':max(world_errors.values()),\'xform_prim_count\':len(world_errors),\'lidar_count\':sum(p.GetTypeName()==\'OmniLidar\' for p in after.Traverse()),\'fisheye_count\':sum(p.GetTypeName()==\'Camera\' and p.GetName().startswith(\'Fisheye\') for p in after.Traverse()),\'parts\':geometry,\'motion_cases\':motion,\'scene\':manifest[\'scene\'],\'asset\':manifest[\'asset\'],\'engine_capture\':\'pending; separate report\'}\n(WORK/\'validation.json\').write_text(json.dumps(report,indent=2))\nprint(json.dumps(report));assert report[\'passed\']\n', 'sha256': '24d0cb08bace123bdb6bc5059f03d17c83875faaa1bdc246b7be9cb3634a3f55'}, 'mesh_scene18/README.md': {'text': '# Scene18：mesh 挖掘机替换\n\n状态：已于2026-10-12在单卡实例构建并通过静态、运动与MCAP采集验证。\n\n## 打开新场景\n\n在远端 Isaac Sim 的 **File → Open** 打开：\n\n```text\n/root/gpufree-data/IsaacSim_Asset/combine_stage/combine_scene_18_terrain_fisheye_mesh.usda\n```\n\n打开资产不需要运行构建脚本。原场景17保留不变；新场景包含五部件mesh挖掘机，铲斗完整保留铲齿，其他场景与传感器沿用场景17。新场景仍依赖原有场景15、传感器和环境素材，不能只拷贝单个combine文件当成独立完整场景。\n\n独立挖掘机资产：\n\n```text\n/root/gpufree-data/IsaacSim_Asset/excavator_module_set/Excavator_Mesh_Contract/Excavator_Mesh_Contract.usda\n```\n\n该资产及其 `geometry/` 是相对路径的完整mesh挖掘机，默认根节点仍为 `/Excavator`。全部网格、顶点颜色、法线及拓扑保留；顶点颜色通过 UsdPreviewSurface 显示，不需要外部贴图下载。\n\n## 后续采集配置\n\n采集器配置的 `scene` 必须明确指向场景18；原有版本默认仍可能打开场景16。本次没有修改旧版本的默认配置。\n\n沿用之前的 v06 常驻资源方案：`mode=offline`、`capture.resource_policy=keepalive`、RealTimePathTracing、16个预热子帧＋2个正式子帧。旧场景录制的轨迹可能绑定旧场景哈希，应在新场景重新记录，或明确完成轨迹迁移，不能直接关闭哈希检查。\n\n本次三组验证的任务配置可查看：\n\n```text\n/root/gpufree-data/semantic/output/mesh_scene18/smoke_20261012_094955/job.json\n```\n\n## 本目录脚本\n\n| 文件 | 作用 |\n|---|---|\n| analyze_alignment.py | 利用同序3DGS点恢复历史刚体变换，跨部件和原始mesh核对 |\n| build_assets.py | 构建新mesh资产与场景18；拒绝覆盖已存在的目标 |\n| validate_assets.py | 非几何节点、变换、网格数组、材质和9组内存运动验证 |\n| runtime.py | 调用已安装Isaac USD解释器，不启动Kit、不下载依赖 |\n| prepare_capture.py | 根据场景18本身的传感器安装位姿生成3组测试轨迹 |\n| capture_supervisor.py | 复用保留的v06采集代码，有限时运行、录包校验和解码 |\n| start_capture.py | 启动一次新的独立测试，遇到已有Kit时不停止它 |\n| status_capture.py | 读取本任务采集状态与日志 |\n| prepare_operation.py | 本地Windows侧生成审计工具的部署/执行脚本 |\n| pull_artifacts.py | 本地Windows侧通过已登记身份拉取生成资产和验证证据 |\n\n这些脚本是资产制作与验证工具，不替换已有Sensor Visualizer面板。\n\n## 记录与回退\n\n- 完整方案：`../docs/20261012_scene17_mesh_excavator_implementation_plan.md`。\n- 执行报告：`../docs/20261012_scene18_mesh_excavator_execution_report.md`。\n- `build_manifest.json`：文件来源、哈希、校正矩阵、网格统计和备份位置。\n- `validation.json`：静态与内存运动检查。\n- 本地 `evidence/`：实际采集报告、日志和12张从MCAP解码的图像。\n- 本地 `deployed/`：生成mesh资产的校验一致副本；combine场景的旧环境依赖未全部拷贝到此处。\n- 回退：重新打开场景17，无需修改旧资产或系统环境。\n', 'sha256': '2f14550f74b848697a7f9d28d715cbe368b2d9c5ef917d26ca47cc5f477db1a0'}, 'docs/20261012_scene17_mesh_excavator_implementation_plan.md': {'text': '# 场景17挖掘机 mesh 替换实现方案\n\n记录日期：2026-10-12。用户已授权保存完整方案并在远端实施。\n\n## 1. 核心目标及用户明确的例外\n\n以 `/root/gpufree-data/IsaacSim_Asset/combine_stage/combine_scene_17_terrain_fisheye.usda` 为基准，保留现有装配与控制结构，为五个挖掘机部件替换 mesh 几何，并生成独立的新场景。\n\n铲斗直接采用完整带齿的 `bucket_only_full_teeth_mesh`，保留其全部几何，不要求与原来不带齿的 3DGS 铲斗内容一致。铲斗的安装原点、关节轴、角度零点和运动方式仍保持当前定义。\n\n必须保持：整机世界位置、旋转和尺度基准；各部件坐标系原点、轴向、关节连接位置、角度零点与运动方向；全部雷达及相机的路径、参数、安装位置和姿态；场景17中用户摆放的物体、背景、灯光和其他设置；脚本控制与 TF 发布依赖的节点结构。\n\n## 2. 目标文件与替换范围\n\n计划生成：\n\n```text\n/root/gpufree-data/IsaacSim_Asset/excavator_module_set/Excavator_Mesh_Contract/\n  Excavator_Mesh_Contract.usda\n  geometry/                         # 校正后的网格、材质与必要贴图\n  manifest.json                    # 原始来源、变换、哈希与验证摘要\n\n/root/gpufree-data/IsaacSim_Asset/combine_stage/\n  combine_scene_18_terrain_fisheye_mesh.usda\n```\n\n保留场景17及原有3DGS资产，不覆盖用户已有修改。若目标文件已存在，先核对归属并备份，不盲目覆盖。\n\nmesh 来源为已有 `/root/gpufree-data/IsaacSim_Asset/excavator_module_set/Sim_Fangshan_02/waji_mesh_corrected.usdc`。几何对应为：\n\n| 当前部件 | 来源 mesh |\n|---|---|\n| track_link | track_mesh |\n| swing_link | operator_cab_mesh |\n| boom_link | boom_mesh |\n| arm_link | small_arm_mesh |\n| bucket_link | bucket_only_full_teeth_mesh |\n\n## 3. 坐标与尺寸处理\n\n保留 `/World/Excavator`、五个 `*_link` 和 `Joints` 的现有定义。每个部件下面设置固定几何校正变换，将来源 mesh 坐标映射到当前部件坐标系。\n\n```text\n/World/Excavator\n  boom_link                  # 保留部件原点和控制\n    Visuals\n      MeshAlignment          # mesh 到当前部件坐标系的固定校正\n        Mesh                 # 网格、材质和 UV\n```\n\n世界中的 mesh = 当前部件世界变换 × mesh 到该部件坐标系的校正变换（列向量说明；USD Gf 行向量矩阵需对应转置）。\n\n保留整机位置、旋转和缩放关系，不将部件原点重置为几何中心。优先依据历史变换记录恢复坐标映射，并以已有几何数据交叉核对；避免重复应用原始装配中的2.4倍缩放，不通过独立拉伸部件强行匹配包围盒。带齿铲斗以关节安装位置为对齐基准，新增铲齿导致边界改变是预期差异。\n\n## 4. 资产组装\n\n沿用当前挖掘机的关节、刚体、Articulation 和控制定义，只复用旧 mesh 文件的几何、材质、UV和贴图。引用独立部件时须保留有效的材质绑定与资产路径；不引入来源文件的相机、灯光或旧关节。\n\n新场景明确替换旧几何引用，确保原3DGS部件不再参与渲染或雷达求交。全部传感器路径及挂载关系保持不变。不因视觉几何替换自动增加碰撞体或重新计算质量与惯量。\n\n## 5. 执行顺序\n\n1. 固定基准：记录场景17及直接依赖文件的版本、哈希，提取部件、关节、传感器配置，并保存可恢复基准。\n2. 确定映射：核对五个 mesh 的单位、坐标、缩放和历史对齐依据，得到校正矩阵。无法由数据证明的部分明确记录，不能用猜测替代。\n3. 组装资产：保留装配结构，接入 mesh、材质和依赖，保存来源及变换清单。\n4. 派生场景：从场景17创建新文件，替换挖掘机几何，保留其余内容。\n5. 静态检查：比较根节点、部件原点、关节、传感器和非挖掘机场景内容，输出数值一致性报告。\n6. 运动检查：覆盖初始姿态、整机平移与旋转、各关节正负角度，验证无错误绕转、脱节或传感器漂移。数学变换验证与实际引擎运动测试分别报告。\n7. 采集检查：使用已有采集链路进行少量图像、点云和TF验证；使用独立验证进程，不打断用户已有 GUI。若现有会话或资源不允许引擎验证，明确报告已完成项及未执行项。\n\n## 6. 验收标准\n\n- 必须一致：整机及部件坐标系、关节定义、传感器安装位姿、其余场景内容。\n- 需要对齐验证：五部件尺寸、方向、安装位置和连接处；优先核对变换依据及几何特征，不只比外包围盒。\n- 允许变化：完整铲齿，以及 mesh 与3DGS表示差异带来的表面细节、成像和雷达回波变化。\n- 数据记录：保存每个来源文件、源 prim、目标 prim、校正矩阵、单位、原点和验证误差。浮点误差须量化。\n- 本轮以资产替换和一致性为主；性能可顺带测量，但不承诺 mesh 一定更快。\n\n## 7. 工具与操作边界\n\n优先使用实例已有 Isaac USD Python API（Sdf、Usd、UsdGeom、Gf、UsdShade）及现有项目采集工具，不下载或升级外部依赖。所有远端操作使用已登记身份和审计工具，源代码、文档和验证报告保存在本地项目与远端对应项目目录。无需修改系统、驱动、桌面、SSH或运行环境。\n\n回退方式：打开原场景17和原3DGS资产即可恢复原有资产方案；原文件不被替换。实施结果另存报告，不把计划中的检查写成已经完成。\n', 'sha256': 'bc6a9e3011f8f34c40ee2bb31e772f518b4fd40a0b5e73f9ef4c5da82a9f8533'}, 'docs/20261012_scene18_mesh_excavator_execution_report.md': {'text': '# 场景18 mesh挖掘机替换：执行报告\n\n日期：2026-10-12。目标：在场景17基础上替换五个3DGS挖掘机部件，保留坐标、关节、传感器和其他场景内容。用户明确要求采用完整带齿mesh铲斗。\n\n## 交付结果\n\n新组合场景：\n\n```text\n/root/gpufree-data/IsaacSim_Asset/combine_stage/combine_scene_18_terrain_fisheye_mesh.usda\n```\n\n新挖掘机资产：\n\n```text\n/root/gpufree-data/IsaacSim_Asset/excavator_module_set/Excavator_Mesh_Contract/Excavator_Mesh_Contract.usda\n```\n\n方案、源代码分别位于项目的 `docs/20261012_scene17_mesh_excavator_implementation_plan.md` 和 `mesh_scene18/`，本地与远端均保存。旧场景、旧3DGS资产及旧采集代码没有被替换。\n\n## 坐标校正依据\n\n从当前原始坐标的track 3DGS和历史校正坐标的track 3DGS恢复同一刚体变换，使用 cab、boom、arm 的同序点独立交叉核对。最大残差为 `1.65613255e-7` 原始坐标单位。不是用最近邻ICP将不同形状强行拟合。\n\n原始完整mesh与现有校正mesh均为317675个顶点；应用该变换后，按1mm网格舍入的顶点匹配率为99.9946486%，128个均匀索引抽样点的最近顶点最大距离为 `1.21677366e-7` 原始坐标单位。舍入匹配率和抽查不等于逐顶点全量精确对应证明，二者作为历史变换的交叉证据。\n\nUSD采用行向量记法：\n\n```text\nmesh_world = mesh_corrected * corrected_to_raw * existing_Visuals * existing_link_world\n```\n\n保留现有Visuals中的原始坐标到当前部件坐标的矩阵，因此2.4倍素材缩放仍只应用一次。校正矩阵存于每个Visuals下的新MeshAlignment节点。根节点、刚体部件节点和关节坐标系不被重新居中。\n\n## 几何与材质\n\n| 当前部件 | 来源mesh | 顶点 | 三角面 |\n|---|---|---:|---:|\n| track_link | track_mesh | 101771 | 200806 |\n| swing_link | operator_cab_mesh | 116099 | 229912 |\n| boom_link | boom_mesh | 57635 | 114781 |\n| arm_link | small_arm_mesh | 23764 | 47013 |\n| bucket_link | bucket_only_full_teeth_mesh | 18406 | 36356 |\n| 合计 | | 317675 | 628868 |\n\n逐部件验证原始points、faceVertexCounts、faceVertexIndices、normals和Col颜色数组与新资产完全相同。mesh本身没有材质绑定，故将原有线性RGBA顶点色的RGB映射为displayColor，再绑定UsdPreviewSurface；alpha检查为全1，roughness设为0.8、metallic为0。没有添加外部纹理，没有引入来源文件的相机、灯光或旧关节。\n\n铲斗完整保留铲齿。mesh和3DGS的表面表示及细节本来不同；相同装配尺度和坐标映射不意味着表面轮廓、外包围盒或点云逐点完全相同。本次没有通过非均匀拉伸或修改顶点来消除这些差异。\n\n## 静态与运动检查\n\n- 889个非替换几何节点：类型、活动状态、schemas、自定义数据、属性和关系对比无差异。\n- 343个Xformable节点：替换前后世界矩阵最大绝对差为0。\n- 13路OmniLidar、4路鱼眼相机保留；其他场景相机也在上述非几何对比范围内。\n- 合成后的活动场景中Gaussian prim数量为0。\n- 9组内存规定运动检查：初始姿态，组合正负角度＋整机变换，以及大臂、小臂、铲斗各自±15°。保留节点的世界矩阵差为0，mesh变换链最大误差为 `8.88e-16`。\n- 内存变换检查不是动力学仿真认证；实际引擎规定运动与录包另见下节。\n\n原场景及依赖文件哈希存于 `mesh_scene18/backups/20261012T094456Z/source_hashes.json`。构建和静态验证时均未变化。源场景17 SHA256：`2e1503a3b34fc23b2f2273fb502c2c0a1e83b39722eaa075bdd4fe94372d51a2`。\n\n## 实际引擎与MCAP验证\n\n独立无窗口Isaac进程，采用保留的 `single06_lab/frozen_runtime` 代码，未修改该版本。单卡L40；RealTimePathTracing、DLSS Quality、16个相机预热子帧＋2个正式子帧、传感器资源常驻。\n\n输入为场景18生成的三组状态：初始状态；大臂/小臂/铲斗+15°并平移、旋转整机；三关节-15°并平移、旋转整机。回转关节保持原控制策略。\n\n测试输出：\n\n```text\n/root/gpufree-data/semantic/output/mesh_scene18/smoke_20261012_094955/\n  result.json\n  engine.log\n  job.json\n  input_trajectory/\n  decoded.json\n  images/{front,back,left,right}/\n  captures/20261012_175012_482511_75deddca/bag_unified/\n```\n\n| 验证项 | 结果 |\n|---|---|\n| 引擎退出、数据验证、图片解码 | 均通过，退出码0 |\n| 采集组数 | 3 |\n| 点云 | 13路×3组＝39帧 |\n| 图像 | 4路×3组＝12张，1920×1080 RGB |\n| MCAP | 41650864字节，约41.65MB |\n| 话题、消息 | 32个话题、92条消息 |\n| 每组TF边 | 19 |\n| 源轨迹时刻 | 0、0.1、0.2秒 |\n| 实际消息时刻 | 133333333、233333333、333333333纳秒 |\n| TF与记录的传感器矩阵最大误差 | 8.88e-15 |\n| 整机位置对输入轨迹最大误差 | 5.29e-8米 |\n| 关节角对输入轨迹最大误差 | 7.29e-9弧度 |\n| 图像内参与消息内容哈希 | 验证通过 |\n| 新场景磁盘文件 | 测试前后哈希一致 |\n\n从实际MCAP解码图片，检查了首组前后鱼眼图像；前向图像可见完整带齿mesh铲斗、大臂和用户摆放的物体，颜色正常。全部图像通过非空、尺寸、格式和时间对应检查；不将这些检查称为像素级复现3DGS。\n\n三组采集含排空约13.79秒，独立引擎进程约67.26秒。与先前场景16的性能实验输入不同，不能据此宣称性能提升倍数。\n\n## 警告与限制\n\n日志0条Error、103条Warning。可见类型包括已有的RobotMotionSchema路径、动画节点注册、音频设备、Cache Server、nvperf库、MotionBVH关闭提示和hydratexture接口释放警告。未观察到新mesh的材质/几何加载失败，录包和位姿验证通过，但不宣称引擎warning已解决。原采集链路的MotionBVH设置未变，本轮为冻结采集。\n\n此次不修改系统、驱动、桌面、SSH或Python依赖，没有新增外部下载。仅使用已有USD、NumPy、Isaac和ROS环境。部署曾因工具把编码文本判为疑似秘密而被拒绝，改用可审阅UTF-8源码传输后成功；一次构建前哈希检查遇到USDZ内部路径，修正为对外层包文件哈希后重新执行。该次失败发生于创建资产之前，没有覆盖源文件。\n\n## 使用与回退\n\n在远端File → Open打开场景18即可检查和编辑资产。采集任务的scene参数需明确指定场景18；旧版本默认配置没有被修改。旧轨迹若绑定场景16哈希，需要在新场景重录或明确迁移，不能直接绕过校验。\n\n回退只需重新打开场景17。所有源资产保留；本地另保存新挖掘机资产及验证报告、日志和解码图片的哈希一致副本。\n', 'sha256': 'cbb696d9516e136ae2150e36cf594215ae066dbc0dea79d64a79cb491419851d'}}
written=[]
for rel,item in files.items():
 target=root/rel
 assert target.resolve().is_relative_to(root)
 data=item['text'].encode('utf-8')
 assert hashlib.sha256(data).hexdigest()==item['sha256']
 if target.exists() and target.read_bytes()!=data:
  backup=root/'mesh_scene18/backups'/datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')/rel
  backup.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(target,backup)
 target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes(data)
 assert hashlib.sha256(target.read_bytes()).hexdigest()==item['sha256']
 written.append({'path':str(target),'sha256':item['sha256']})
print(json.dumps({'deployed':written}))
